package com.crypto.laplace.execution;

import com.crypto.common.enums.PositionSide;
import com.crypto.laplace.model.*;
import com.crypto.laplace.persistence.*;
import com.crypto.laplace.service.StartupMarketUniverseService;
import com.crypto.laplace.pool.LaplaceCoinPoolService;
import com.crypto.laplace.config.LaplaceStrategyProperties;
import com.crypto.domain.model.Kline;
import java.math.*;import java.time.*;import java.util.*;
import lombok.extern.slf4j.Slf4j;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Slf4j @Service
public class LaplacePaperExecutionService {
 public static final String STRATEGY="LAPLACE_KERNEL_REGRESSION_30M", VERSION="1.0";private static final int SCALE=12;
 private final LaplacePaperPositionRepository positions;private final LaplaceTradeEventRepository events;private final LaplaceExecutionPriceProvider prices;private final LaplacePnlCalculator pnl;private final LaplaceStrategyProperties properties;private final LaplaceTradeJsonlWriter writer;
 private final StartupMarketUniverseService universe; private final LaplaceCoinPoolService coinPool;
 @Autowired
 public LaplacePaperExecutionService(LaplacePaperPositionRepository positions,LaplaceTradeEventRepository events,LaplaceExecutionPriceProvider prices,LaplacePnlCalculator pnl,LaplaceStrategyProperties properties,LaplaceTradeJsonlWriter writer,StartupMarketUniverseService universe,LaplaceCoinPoolService coinPool){this.positions=positions;this.events=events;this.prices=prices;this.pnl=pnl;this.properties=properties;this.writer=writer;this.universe=universe;this.coinPool=coinPool;}
 public LaplacePaperExecutionService(LaplacePaperPositionRepository positions,LaplaceTradeEventRepository events,LaplaceExecutionPriceProvider prices,LaplacePnlCalculator pnl,LaplaceStrategyProperties properties,LaplaceTradeJsonlWriter writer,StartupMarketUniverseService universe){this.positions=positions;this.events=events;this.prices=prices;this.pnl=pnl;this.properties=properties;this.writer=writer;this.universe=universe;this.coinPool=null;}
 @Transactional public LaplacePaperPositionEntity open(LaplaceSignalResult signal,PositionSide side,String reversalId,String positionBefore){
  assertNoOpen(signal.symbol());MarketExecutionAction action=side==PositionSide.LONG?MarketExecutionAction.LONG_OPEN:MarketExecutionAction.SHORT_OPEN;var quote=prices.quote(signal.symbol(),action);Instant requested=Instant.now();BigDecimal price=quote.value();BigDecimal margin=coinPool==null?properties.getLaplace().getMarginPerPositionUsdt():coinPool.dailyMargin(); int leverage=10; BigDecimal notional=margin.multiply(BigDecimal.valueOf(leverage));BigDecimal quantity=notional.divide(price,SCALE,RoundingMode.DOWN);BigDecimal feeRate=properties.getLaplace().getTakerFeeRate();
  if(quantity.signum()<=0 || margin.signum()<=0 || notional.signum()<=0)throw new IllegalStateException("INVALID_QUANTITY");BigDecimal fee=notional.multiply(feeRate).setScale(SCALE,RoundingMode.HALF_UP);String signalId=entryKey(signal,side);Instant now=Instant.now();
  var p=LaplacePaperPositionEntity.builder().id(UUID.randomUUID().toString()).strategy(STRATEGY).strategyVersion(VERSION).symbol(signal.symbol()).side(side).status(LaplacePositionStatus.OPEN).entrySignalId(signalId).entryRawSignal(signal.entrySignal().name()).signalInverted(true).entryCandleCloseTime(signal.signalCandleCloseTime()).entryTime(now).entrySignalClosePrice(BigDecimal.valueOf(signal.signalCandleClose())).entryExecutionPrice(price).margin(margin).quantity(quantity).notional(notional).leverage(leverage).entryFeeRate(feeRate).entryFee(fee).stopLossPct(new BigDecimal("0.055")).stopPrice(side==PositionSide.LONG?price.multiply(new BigDecimal("0.945")):price.multiply(new BigDecimal("1.055"))).build();positions.saveAndFlush(p);
  log.info("LAPLACE_MARKET_ENTRY_EXECUTED strategy={} symbol={} side={} orderType=MARKET executionPriceType={} executionPrice={} notional={} leverage={}",STRATEGY,signal.symbol(),side,quote.executionPriceType(),price,notional,leverage);
  Map<String,Object> payload=base(signal,"ENTRY",p,UUID.randomUUID().toString(),reversalId);payload.put("side",side);payload.put("rawEntrySignal",signal.entrySignal());payload.put("rawStrongReversalSignal",signal.strongReversalSignal());payload.put("effectiveExecutionSide",side);payload.put("signalInverted",true);payload.put("initialCapitalUsdt",properties.getLaplace().getInitialCapitalUsdt());payload.put("positionBefore",positionBefore);payload.put("positionAfter",side);payload.put("entryReason",reversalId==null?"CONFIRMED_LAPLACE_"+side:"CONFIRMED_LAPLACE_REVERSAL");payload.put("signalDetectedAt",requested);payload.put("executionRequestedAt",requested);payload.put("executionTime",now);payload.put("orderType","MARKET");payload.put("executionAction",action);payload.put("priceSource",quote.source());payload.put("bestBid",quote.bestBid());payload.put("bestAsk",quote.bestAsk());payload.put("executionPriceType",quote.executionPriceType());payload.put("executionPrice",price);payload.put("margin",margin);payload.put("leverage",leverage);payload.put("notional",notional);payload.put("quantity",quantity);payload.put("takerFeeRate",feeRate);payload.put("entryFeeRate",feeRate);payload.put("entryFee",fee);payload.put("status",p.getStatus());BigDecimal entryCapital=realizedCapital(),entryDaily=realizedDailyPnl(now);addCapitalAudit(payload,entryCapital,entryCapital,entryDaily,entryDaily,margin);saveEvent(payload,"ENTRY",reversalId,p);return p;
 }
 @Transactional public ReversalOutcome reverse(LaplaceSignalResult signal,LaplacePaperPositionEntity expected,PositionSide target,boolean openTarget){
  LaplacePaperPositionEntity p=singleOpenForUpdate(signal.symbol());if(!p.getId().equals(expected.getId()))throw new IllegalStateException("POSITION_STATE_CONFLICT");String exitSignalId=reversalKey(signal,target);if(p.getExitSignalId()!=null)throw new IllegalStateException("DUPLICATE_EXECUTION_BLOCKED");String reversalId=UUID.randomUUID().toString();Instant requested=Instant.now();MarketExecutionAction action=p.getSide()==PositionSide.LONG?MarketExecutionAction.LONG_CLOSE:MarketExecutionAction.SHORT_CLOSE;var quote=prices.quote(signal.symbol(),action);Instant now=Instant.now();BigDecimal capitalBefore=realizedCapital();CloseValues values=applyClose(p,quote.value(),now,LaplacePositionStatus.CLOSED_BY_SIGNAL,openTarget?"OPPOSITE_CONFIRMED_LAPLACE_SIGNAL":"OPPOSITE_SIGNAL_OUTSIDE_ENTRY_UNIVERSE");BigDecimal exitNotional=values.exitNotional();BigDecimal exitFee=values.exitFee();var result=values.pnl();
  if(p.getLeverage()!=10)log.warn("LAPLACE_LEGACY_POSITION_SIZING_PRESERVED symbol={} positionId={} notional={} leverage={}",p.getSymbol(),p.getId(),p.getNotional(),p.getLeverage());
  p.setExitSignalId(exitSignalId);positions.saveAndFlush(p); if(coinPool!=null)coinPool.positionClosed(p.getSymbol());
  log.info("LAPLACE_MARKET_EXIT_EXECUTED strategy={} symbol={} side={} orderType=MARKET executionPriceType={} executionPrice={} entryNotional={} leverage={}",STRATEGY,signal.symbol(),p.getSide(),quote.executionPriceType(),quote.value(),p.getNotional(),p.getLeverage());
  Map<String,Object> payload=base(signal,"EXIT",p,UUID.randomUUID().toString(),reversalId);payload.put("side",p.getSide());payload.put("closedSide",p.getSide());payload.put("incomingSignal",target);payload.put("positionBefore",p.getSide());payload.put("positionAfter","FLAT");payload.put("exitReason",p.getExitReason());payload.put("entryTime",p.getEntryTime());payload.put("entrySignalClosePrice",p.getEntrySignalClosePrice());payload.put("entryExecutionPrice",p.getEntryExecutionPrice());payload.put("exitExecutionRequestedAt",requested);payload.put("exitTime",now);payload.put("orderType","MARKET");payload.put("executionAction",action);payload.put("priceSource",quote.source());payload.put("bestBid",quote.bestBid());payload.put("bestAsk",quote.bestAsk());payload.put("executionPriceType",quote.executionPriceType());payload.put("exitExecutionPrice",quote.value());payload.put("entryNotional",p.getNotional());payload.put("exitNotional",exitNotional);payload.put("quantity",p.getQuantity());payload.put("notional",p.getNotional());payload.put("leverage",p.getLeverage());payload.put("grossPnl",p.getGrossPnl());payload.put("grossPnlPct",p.getGrossPnlPct());payload.put("entryFee",p.getEntryFee());payload.put("takerFeeRate",p.getEntryFeeRate());payload.put("exitFeeRate",p.getEntryFeeRate());payload.put("exitFee",exitFee);payload.put("totalFee",p.getEntryFee().add(exitFee));payload.put("netPnl",p.getNetPnl());payload.put("netPnlPct",p.getNetPnlPct());payload.put("holdingMinutes",p.getHoldingMinutes());payload.put("status",p.getStatus());BigDecimal dailyBefore=realizedDailyPnl(now).subtract(result.net());addCapitalAudit(payload,capitalBefore,capitalBefore.add(result.net()),dailyBefore,dailyBefore.add(result.net()),p.getMargin());saveEvent(payload,"EXIT",reversalId,p);
  LaplacePaperPositionEntity opened=null;if(openTarget)try{opened=open(signal,target,reversalId,p.getSide().name());}catch(RuntimeException failure){throw new IllegalStateException("REVERSAL_OPEN_FAILED",failure);}return new ReversalOutcome(p,opened,reversalId);
 }
 @Transactional public Optional<LaplacePaperPositionEntity> closeByStop(String positionId,Kline candle,BigDecimal executionPrice,String executionPriceSource){
  LaplacePaperPositionEntity p=positions.findByIdForUpdate(positionId).orElseThrow();if(p.getStatus()!=LaplacePositionStatus.OPEN){log.info("LAPLACE_STOP_CLOSE_NOOP positionId={} status={}",positionId,p.getStatus());return Optional.empty();}
  Instant requested=Instant.now();BigDecimal capitalBefore=realizedCapital();Instant now=Instant.now();CloseValues values=applyClose(p,executionPrice,now,LaplacePositionStatus.CLOSED_BY_STOP_LOSS,"STOP_LOSS_5M");
  p.setStopTriggeredCandleOpenTime(candle.getOpenTime());p.setStopTriggeredCandleCloseTime(candle.getCloseTime());p.setStopTriggeredCandleHigh(candle.getHigh());p.setStopTriggeredCandleLow(candle.getLow());p.setStopTriggeredCandleClose(candle.getClose());positions.saveAndFlush(p);if(coinPool!=null)coinPool.positionClosed(p.getSymbol());
  String eventId=UUID.randomUUID().toString();Map<String,Object> payload=new LinkedHashMap<>();payload.put("eventType","EXIT");payload.put("eventId",eventId);payload.put("reversalId",null);payload.put("strategy",STRATEGY);payload.put("strategyVersion",VERSION);payload.put("positionId",p.getId());payload.put("symbol",p.getSymbol());payload.put("closedSide",p.getSide());payload.put("positionBefore",p.getSide());payload.put("positionAfter","FLAT");payload.put("exitReason","STOP_LOSS");payload.put("status",p.getStatus());payload.put("stopLossPct",p.getStopLossPct().multiply(BigDecimal.valueOf(100)));payload.put("stopPrice",p.getStopPrice());payload.put("triggerPrice",p.getSide()==PositionSide.LONG?candle.getLow():candle.getHigh());payload.put("triggeredAt",candle.getCloseTime());payload.put("exitExecutionRequestedAt",requested);payload.put("exitTime",now);payload.put("exitExecutionPrice",executionPrice);payload.put("executionPriceType","SIMULATED_5M");payload.put("executionPriceSource",executionPriceSource);payload.put("entryExecutionPrice",p.getEntryExecutionPrice());payload.put("quantity",p.getQuantity());payload.put("entryNotional",p.getNotional());payload.put("exitNotional",values.exitNotional());payload.put("grossPnl",p.getGrossPnl());payload.put("entryFee",p.getEntryFee());payload.put("exitFee",p.getExitFee());payload.put("totalFee",p.getEntryFee().add(p.getExitFee()));payload.put("netPnl",p.getNetPnl());payload.put("priceMovePct",priceMovePct(p,executionPrice));payload.put("notionalPnlPct",p.getNetPnlPct());payload.put("marginRoiPct",p.getNetPnl().divide(p.getMargin(),SCALE,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)));payload.put("holdingMinutes",p.getHoldingMinutes());BigDecimal dailyBefore=realizedDailyPnl(now).subtract(p.getNetPnl());addCapitalAudit(payload,capitalBefore,capitalBefore.add(p.getNetPnl()),dailyBefore,dailyBefore.add(p.getNetPnl()),p.getMargin());saveEvent(payload,"EXIT",null,p);log.info("LAPLACE_STOP_EXIT_PUBLISHED positionId={} symbol={} exitExecutionPrice={} source={} netPnl={}",p.getId(),p.getSymbol(),p.getExitExecutionPrice(),executionPriceSource,p.getNetPnl());return Optional.of(p);
 }
 public void drainOutbox(){writer.drain();}
 public void beginPricingCycle(){prices.beginCycle();}
 public LaplaceExecutionPriceProvider.RequestMetrics pricingMetrics(){return prices.requestMetrics();}
 private CloseValues applyClose(LaplacePaperPositionEntity p,BigDecimal exitPrice,Instant now,LaplacePositionStatus status,String reason){BigDecimal exitNotional=p.getQuantity().multiply(exitPrice).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal exitFee=exitNotional.multiply(p.getEntryFeeRate()).setScale(SCALE,RoundingMode.HALF_UP);var result=pnl.calculate(p.getSide(),p.getEntryExecutionPrice(),exitPrice,p.getQuantity(),p.getNotional(),p.getEntryFee(),exitFee);p.setStatus(status);p.setExitTime(now);p.setExitExecutionPrice(exitPrice);p.setExitFee(exitFee);p.setGrossPnl(result.gross());p.setGrossPnlPct(result.grossPct());p.setNetPnl(result.net());p.setNetPnlPct(result.netPct());p.setHoldingMinutes(Duration.between(p.getEntryTime(),now).toMinutes());p.setExitReason(reason);return new CloseValues(exitNotional,exitFee,result);}
 private BigDecimal realizedCapital(){return properties.getLaplace().getInitialCapitalUsdt().add(positions.findAll().stream().filter(x->STRATEGY.equals(x.getStrategy())&&x.getStatus()!=LaplacePositionStatus.OPEN).map(x->x.getNetPnl()==null?BigDecimal.ZERO:x.getNetPnl()).reduce(BigDecimal.ZERO,BigDecimal::add));}
 private BigDecimal realizedDailyPnl(Instant at){java.time.ZoneId zone=java.time.ZoneId.of("America/New_York");java.time.LocalDate date=at.atZone(zone).toLocalDate();return positions.findAll().stream().filter(x->STRATEGY.equals(x.getStrategy())&&x.getStatus()!=LaplacePositionStatus.OPEN&&x.getExitTime()!=null&&x.getExitTime().atZone(zone).toLocalDate().equals(date)).map(x->x.getNetPnl()==null?BigDecimal.ZERO:x.getNetPnl()).reduce(BigDecimal.ZERO,BigDecimal::add);}
 private void addCapitalAudit(Map<String,Object> payload,BigDecimal before,BigDecimal after,BigDecimal dailyBefore,BigDecimal dailyAfter,BigDecimal appliedMargin){BigDecimal rate=properties.getLaplace().getMarginPerPositionUsdt().divide(properties.getLaplace().getInitialCapitalUsdt(),SCALE,RoundingMode.HALF_UP);java.time.ZoneId zone=java.time.ZoneId.of("America/New_York");payload.put("capitalBefore",before);payload.put("capitalAfter",after);payload.put("realizedDailyPnlBefore",dailyBefore);payload.put("realizedDailyPnlAfter",dailyAfter);payload.put("marginRate",rate);payload.put("calculatedMargin",before.multiply(rate));payload.put("appliedMargin",appliedMargin);payload.put("capitalCalculationDate",java.time.LocalDate.now(zone));payload.put("capitalTimezone",zone.getId());payload.put("dailyRolloverTime","10:00:05");}
 private BigDecimal priceMovePct(LaplacePaperPositionEntity p,BigDecimal exit){BigDecimal move=p.getSide()==PositionSide.LONG?exit.subtract(p.getEntryExecutionPrice()):p.getEntryExecutionPrice().subtract(exit);return move.divide(p.getEntryExecutionPrice(),SCALE,RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100));}
 private record CloseValues(BigDecimal exitNotional,BigDecimal exitFee,LaplacePnlCalculator.Pnl pnl){}
 boolean hasAvailableBalance(BigDecimal required){return availableBalance().compareTo(required)>=0;}
 BigDecimal availableBalance(){BigDecimal realized=positions.findAll().stream().filter(x->STRATEGY.equals(x.getStrategy())&&x.getStatus()!=LaplacePositionStatus.OPEN).map(x->x.getNetPnl()==null?BigDecimal.ZERO:x.getNetPnl()).reduce(BigDecimal.ZERO,BigDecimal::add);List<LaplacePaperPositionEntity> open=positions.findByStrategyAndStatus(STRATEGY,LaplacePositionStatus.OPEN);BigDecimal locked=open.stream().map(LaplacePaperPositionEntity::getMargin).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal openEntryFees=open.stream().map(x->x.getEntryFee()==null?BigDecimal.ZERO:x.getEntryFee()).reduce(BigDecimal.ZERO,BigDecimal::add);return properties.getLaplace().getInitialCapitalUsdt().add(realized).subtract(locked).subtract(openEntryFees);}
 private void assertNoOpen(String symbol){if(!positions.findOpenForUpdate(STRATEGY,symbol,LaplacePositionStatus.OPEN).isEmpty())throw new IllegalStateException("POSITION_STATE_CONFLICT");}
 public LaplacePaperPositionEntity singleOpenForUpdate(String symbol){List<LaplacePaperPositionEntity>x=positions.findOpenForUpdate(STRATEGY,symbol,LaplacePositionStatus.OPEN);if(x.size()!=1)throw new IllegalStateException("POSITION_STATE_CONFLICT");return x.getFirst();}
 private void saveEvent(Map<String,Object> payload,String type,String reversal,LaplacePaperPositionEntity p){String id=(String)payload.get("eventId");String json=writer.tryJson(payload).orElseThrow(()->new IllegalStateException("TRADE_EVENT_SERIALIZATION_FAILED"));events.save(LaplaceTradeEventEntity.builder().eventId(id).eventType(type).reversalId(reversal).positionId(p.getId()).symbol(p.getSymbol()).payloadJson(json).jsonlWritten(false).createdAt(Instant.now()).build());log.info("LAPLACE_TRADE_EVENT_PUBLISHED eventId={} eventType={} symbol={}",id,type,p.getSymbol());}
 private Map<String,Object> base(LaplaceSignalResult s,String type,LaplacePaperPositionEntity p,String eventId,String reversal){Map<String,Object>m=new LinkedHashMap<>();m.put("eventType",type);m.put("eventId",eventId);m.put("reversalId",reversal);m.put("strategy",STRATEGY);m.put("strategyVersion",VERSION);m.put("positionId",p.getId());m.put("symbol",s.symbol());m.put("timeframe",s.timeframe());m.put("kernel",s.kernel());m.put("bandwidth",s.bandwidth());m.put("source",s.source());m.put("repaint",s.repaint());m.put("startupUniverseSessionId",universe.sessionId());m.put("startupVolumeValue",universe.startupVolume(s.symbol()));m.put("minimumVolumeThreshold",universe.minimumVolumeThreshold());m.put("inStartupEntryUniverse",universe.symbols().contains(s.symbol()));m.put("signalCandleOpenTime",s.signalCandleOpenTime());m.put("signalCandleCloseTime",s.signalCandleCloseTime());m.put("signalCandleClose",s.signalCandleClose());m.put("regressionCurrent",s.regressionCurrent());m.put("regressionPrevious",s.regressionPrevious());m.put("regressionTwoBarsAgo",s.regressionTwoBarsAgo());m.put("currentSlope",s.currentSlope());m.put("previousSlope",s.previousSlope());m.put("currentAtr14",s.currentAtr14());m.put("previousAtr14",s.previousAtr14());m.put("currentNormalizedSlope",s.currentNormalizedSlope());m.put("previousNormalizedSlope",s.previousNormalizedSlope());m.put("entryThreshold",s.entryThreshold());m.put("reversalThreshold",s.reversalThreshold());m.put("confirmationBars",s.confirmationBars());m.put("entrySignal",s.entrySignal());m.put("strongReversalSignal",s.strongReversalSignal());m.put("rawEntrySignal",s.entrySignal());m.put("rawStrongReversalSignal",s.strongReversalSignal());m.put("signalInverted",true);return m;}
 public static String entryKey(LaplaceSignalResult s,PositionSide side){return STRATEGY+":"+s.symbol()+":"+s.signalCandleCloseTime()+":ENTRY:"+side;}public static String reversalKey(LaplaceSignalResult s,PositionSide side){return STRATEGY+":"+s.symbol()+":"+s.signalCandleCloseTime()+":REVERSAL:"+side;}
 public record ReversalOutcome(LaplacePaperPositionEntity closed,LaplacePaperPositionEntity opened,String reversalId){}
}
